package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import java.io.*;
public final class Stage52ReopenInstrumentation extends Instrumentation{
 String phase;
 @Override public void onCreate(Bundle b){super.onCreate(b);phase=b.getString("phase","upgrade");start();}
 @Override public void onStart(){Bundle out=new Bundle();try{Context c=getTargetContext();long deadline=android.os.SystemClock.elapsedRealtime()+45000;while(android.os.SystemClock.elapsedRealtime()<deadline){DurableCode.awaitReady();if(ProjectRuntime.active.planner!=null&&PlannerExperience.model!=null)break;Thread.sleep(100);}if(ProjectRuntime.active.planner==null||Math.abs(ProjectRuntime.jump(.5f,0)+24)>.001||PlannerExperience.model==null)throw new AssertionError("compiled code or learned state was not restored: "+DurableCode.status+" / "+ProjectRuntime.error);if(c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionCode!=(phase.equals("core")?510000:500001))throw new AssertionError("Android did not parse the increased versionCode");SceneDraft fixture=RuntimeProgram.fixture();CreatorSession.Result plan=ScenePlanner.plan("fito arma una fiesta con bani",fixture,false);if(plan.commit==null||plan.commit.actions.size()!=3)throw new AssertionError("reopened compiled planner not used");if(phase.equals("core")&&!DurableCode.status.startsWith("Recompilé"))throw new AssertionError("approved code was not recompiled against changed core: "+DurableCode.status);if(phase.equals("fresh")&&ApkSigning.prefs(c).contains("sealed"))throw new AssertionError("private authority must not travel in APK");out.putString("stream","PASS STAGE52_REOPEN "+phase+" compiled planner, animation and own learned weights restored; owner authority "+ApkSigning.prefs(c).contains("sealed")+"\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,out);}}
}
